                # Locate ends of this contiguous diagonal run.
                r0, c0 = r, c
                while (r0 - dr, c0 - dc) in cells:
                    r0, c0 = r0 - dr, c0 - dc
                r1, c1 = r, c
                while (r1 + dr, c1 + dc) in cells:
                    r1, c1 = r1 + dr, c1 + dc

